CREATE OR REPLACE FUNCTION public.criar_questionario_com_prazo(_titulo text,_descricao text,_anonimo boolean,_perguntas jsonb,_expira_em date DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE novo uuid; BEGIN novo := public.criar_questionario(_titulo,_descricao,_anonimo,_perguntas); UPDATE public.questionarios_internos SET expira_em=_expira_em WHERE id=novo; RETURN novo; END $$;
CREATE OR REPLACE FUNCTION public.editar_questionario_com_prazo(_id uuid,_titulo text,_descricao text,_perguntas jsonb,_expira_em date DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.editar_questionario(_id,_titulo,_descricao,_perguntas); UPDATE public.questionarios_internos SET expira_em=_expira_em WHERE id=_id; END $$;